//! 🤝️ Multiple authored restrictions close each original scan before admitting the next actual source.
use super::*;
/// 🧵️ Child frames are born and retired independently under the same original deletion caller.
pub struct AllRowReferences<A:CursorClose,B:CursorClose>{left:Option<Box<A>>,right:Option<Box<B>>,allowed:Option<bool>,phase:u8,closing:bool}
impl<R:EntityRow,A:RowDeletionGuard<R>,B:RowDeletionGuard<R>> RowDeletionGuard<R> for AllRowReferences<A,B>{
 fn new()->Self{Self{left:None,right:None,allowed:None,phase:0,closing:false}}
 fn demand(&self,row:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid());}match self.phase{0=>Ok(birth::<A>()),1=>nested(self.left.as_ref().ok_or_else(invalid)?.demand(row,original,body.saturating_sub(2))?,2),2=>nested(cursor_demand(&self.left,body.saturating_sub(1))?,1),3=>Ok(birth::<B>()),4=>nested(self.right.as_ref().ok_or_else(invalid)?.demand(row,original,body.saturating_sub(2))?,2),5=>nested(cursor_demand(&self.right,body.saturating_sub(1))?,1),_=>Err(invalid())}}
 fn advance(&mut self,row:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=<Self as RowDeletionGuard<R>>::demand(self,row,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{0=>{self.left=Some(Box::new(A::new()));self.phase=1;},1=>{let c=self.left.as_mut().ok_or_else(invalid)?;p=add(c.advance(row,original,body.saturating_sub(2),child(g,2)).map_err(|e|tag(e,2))?.progress(),2)?;if let Some(allowed)=c.result(){self.allowed=Some(allowed);c.begin_close();self.phase=2;}},2=>{p=add(close_cursor(&mut self.left,child(g,1)).map_err(|e|tag(e,1))?,1)?;if self.left.is_none(){self.phase=if self.allowed==Some(false){99}else{3};}},3=>{self.right=Some(Box::new(B::new()));self.phase=4;},4=>{let c=self.right.as_mut().ok_or_else(invalid)?;p=add(c.advance(row,original,body.saturating_sub(2),child(g,2)).map_err(|e|tag(e,2))?.progress(),2)?;if let Some(allowed)=c.result(){self.allowed=Some(allowed);c.begin_close();self.phase=5;}},5=>{p=add(close_cursor(&mut self.right,child(g,1)).map_err(|e|tag(e,1))?,1)?;if self.right.is_none(){self.phase=99;}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy combined reference restrictions")?;Ok(if self.phase==99{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<bool>{if self.phase==99&&!self.closing{self.allowed}else{None}}
 fn begin_close(&mut self){self.closing=true;if let Some(c)=self.left.as_mut(){c.begin_close();}if let Some(c)=self.right.as_mut(){c.begin_close();}}
}
impl<A:CursorClose,B:CursorClose> CursorClose for AllRowReferences<A,B>{fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if self.left.is_some(){cursor_demand(&self.left,b)}else if self.right.is_some(){cursor_demand(&self.right,b)}else{Ok(scalar(0))}}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let p=if self.left.is_some(){close_cursor(&mut self.left,g)?}else if self.right.is_some(){close_cursor(&mut self.right,g)?}else{Default::default()};Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}fn terminal_is_empty(&self)->bool{self.closing&&self.left.is_none()&&self.right.is_none()}}
impl<A:CursorClose,B:CursorClose> Drop for AllRowReferences<A,B>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"combined original references retain a child scan");}}
